1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.rest.function.common.MembershipLevels;
11	
12	/**
13	 * Emits an audit trail entry, via the dedicated {@code AUDIT} logger, for a
14	 * successfully created owner. The line carries the owner id, the assigned
15	 * memberId, the registrationDate and the assigned membershipLevel.
16	 *
17	 * <p>In addition to that human-readable line, an immutable {@link OwnerCreatedEvent} is
18	 * emitted as a compact JSON object on the same {@code AUDIT} logger, giving the trail a
19	 * machine-readable record carrying a monotonic {@code seq}, the owner id, the owner's
20	 * memberId and the membership level.
21	 */
22	public class AuditOwnerCreated {
23	
24	    private static final Logger audit = LoggerFactory.getLogger("AUDIT");
25	
26	    /** Monotonically increasing sequence shared by every owner-created event. */
27	    private static final AtomicLong SEQUENCE = new AtomicLong();
28	
29	    public void service(@Val Owner owner) {
30	        audit.info(
31	                "Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
32	                owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
33	                MembershipLevels.of(owner));
34	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
35	                owner.getMemberId(), MembershipLevels.of(owner), OwnerCreatedEvent.OWNER_CREATED);
36	        audit.info(event.toJson());
37	    }
38	}
