1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Immutable structured audit event emitted, alongside the human-readable audit line, when an
5	 * owner is created (see {@link AuditOwnerCreated}). Serialised to a compact JSON object so the
6	 * audit trail carries a machine-readable record of every create.
7	 *
8	 * <p>The {@code memberId} field carries the owner's primary identifier — the unified
9	 * {@code <REGION><FY><HASH8><CHK>} memberId — so the event always names whatever identifier is
10	 * primary at the time.
11	 *
12	 * @param seq             monotonically increasing sequence number across all owner creates
13	 * @param ownerId         the created owner's id
14	 * @param memberId        the owner's primary identifier (the memberId)
15	 * @param membershipLevel the owner's membership level at creation
16	 * @param event           the event marker, always {@code OWNER_CREATED}
17	 */
18	public record OwnerCreatedEvent(long seq, Integer ownerId, String memberId, Integer membershipLevel,
19	        String event) {
20	
21	    /** The marker every owner-created event carries. */
22	    public static final String OWNER_CREATED = "OWNER_CREATED";
23	
24	    /** Render this event as a compact JSON object. */
25	    public String toJson() {
26	        return "{\"seq\":" + this.seq
27	                + ",\"ownerId\":" + this.ownerId
28	                + ",\"memberId\":" + quote(this.memberId)
29	                + ",\"membershipLevel\":" + this.membershipLevel
30	                + ",\"event\":" + quote(this.event)
31	                + "}";
32	    }
33	
34	    private static String quote(String value) {
35	        if (value == null) {
36	            return "null";
37	        }
38	        StringBuilder sb = new StringBuilder(value.length() + 2);
39	        sb.append('"');
40	        for (int i = 0; i < value.length(); i++) {
41	            char c = value.charAt(i);
42	            switch (c) {
43	                case '"' -> sb.append("\\\"");
44	                case '\\' -> sb.append("\\\\");
45	                case '\n' -> sb.append("\\n");
46	                case '\r' -> sb.append("\\r");
47	                case '\t' -> sb.append("\\t");
48	                default -> sb.append(c);
49	            }
50	        }
51	        sb.append('"');
52	        return sb.toString();
53	    }
54	}
