2	
3	import net.officefloor.plugin.section.clazz.Flow;
4	import net.officefloor.plugin.variable.Out;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.web.bind.annotation.RequestHeader;
8	
9	/**
10	 * First step of create-owner. Reads the optional {@code Idempotency-Key} header and, when
11	 * it has already created an owner, publishes that originally created owner and takes the
12	 * {@code existing} branch to respond 200 — so a repeated create with a seen key does not
13	 * create a duplicate (which the later identity check would otherwise reject with 409).
14	 *
15	 * <p>Otherwise (no key, or a key not yet seen) it returns normally and the pipeline
16	 * continues to {@link ValidateOwnerFields}. The key is always published as an
17	 * {@link IdempotencyKey} so {@link RecordIdempotentCreate} can record the mapping after a
18	 * fresh owner is saved; a {@code null} value means no key was supplied.
19	 */
20	public class CheckIdempotentCreate {
21	
22	    public void service(@RequestHeader(name = "Idempotency-Key", required = false) String key,
23	            IdempotencyStore idempotencyStore, OwnerRepository ownerRepository,
24	            Out<IdempotencyKey> idempotencyKey, Out<Owner> existingOwner,
25	            @Flow("existing") ExistingOwnerFlow existing) {
26	        idempotencyKey.set(new IdempotencyKey(key));
27	        if (key == null || key.isBlank()) {
28	            return; // no key — continue to create as normal
29	        }
30	        Integer ownerId = idempotencyStore.find(key);
31	        if (ownerId == null) {
32	            return; // key not seen — continue to create as normal
33	        }
34	        Owner owner = ownerRepository.findById(ownerId);
35	        if (owner == null) {
36	            return; // original owner is gone — treat as a fresh create
37	        }
38	        existingOwner.set(owner);
39	        existing.flow(); // respond 200 with the originally created owner; suppresses next
40	    }
41	}
